package io.cascadeshield.sim;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import java.util.*;
import static io.cascadeshield.sim.Models.*;
import static io.cascadeshield.sim.OpsModels.*;
import static io.cascadeshield.sim.AiModels.*;
import static org.junit.jupiter.api.Assertions.*;

/** Explicit unit fixtures; no observations, training records or experimental results. */
class AiArchitectureTest {
    private final ObjectMapper mapper=new ObjectMapper().findAndRegisterModules();
    private RoadGraph graph(){List<Node> nodes=List.of(new Node(1,80.25,13.05),new Node(2,80.251,13.05),new Node(3,80.252,13.05),new Node(4,80.251,13.052));List<Edge> edges=new ArrayList<>();for(Object[] item:List.of(new Object[]{"AB",1L,2L,100d},new Object[]{"BC",2L,3L,100d},new Object[]{"BD",2L,4L,150d},new Object[]{"DC",4L,3L,250d})){long from=(long)item[1],to=(long)item[2];edges.add(new Edge((String)item[0],(String)item[0],from,to,from*10+to,(double)item[3],36,"TEST_FIXTURE_ONLY","residential",(String)item[0],List.of(nodes.get((int)from-1).point().coordinates(),nodes.get((int)to-1).point().coordinates()),Map.of()));}return new RoadGraph(new NetworkFile("TEST_FIXTURE_ONLY","TEST_FIXTURE_ONLY",List.of(13d,80d,14d,81d),nodes,edges,List.of(),Map.of("provenance","TEST_FIXTURE_ONLY")));}
    private State state(){RoadGraph graph=graph();State state=new State();state.networkId=graph.network.networkId();Truck t=new Truck();t.id="T1";t.name="Unit fixture";t.start=graph.node(1).point();t.destination=graph.node(3).point();t.position=t.start.coordinates();t.startNode=1;t.destinationNode=3;t.maxSpeedKph=36;t.capacityKg=1000;t.loadKg=500;t.deadlineSec=100;t.route=graph.route(1,3,36,List.of(),0,0);t.etaSec=20;t.remainingDistanceM=200;t.baselineArrivalSec=20;state.trucks.add(t);state.operations.graph=new OperationalDependencyGraph().build(state);return state;}
    private State disrupted(){State state=state();Incident incident=new Incident();incident.id="I1";incident.type="CLOSURE";incident.physicalId="BC";incident.status="ACTIVE";incident.severity=1;incident.startSec=0;incident.endSec=200;state.incidents.add(incident);return state;}
    private CandidateAction reroute(AiFallbackPipeline pipeline,State state){return pipeline.candidates(state,"T1").candidates().stream().filter(a->a.action().equals("REROUTE")).findFirst().orElseThrow();}
    @Test void sevenTypedInterfacesAreUsableWithFallback(){AiFallbackPipeline pipeline=new AiFallbackPipeline(graph(),mapper);assertInstanceOf(AiArchitecture.PredictionProvider.class,pipeline);assertInstanceOf(AiArchitecture.GraphRiskProvider.class,pipeline);assertInstanceOf(AiArchitecture.CandidateActionGenerator.class,pipeline);assertInstanceOf(AiArchitecture.CounterfactualEvaluator.class,pipeline);assertInstanceOf(AiArchitecture.ConstraintValidator.class,pipeline);assertInstanceOf(AiArchitecture.ActionOptimizer.class,pipeline);assertInstanceOf(AiArchitecture.DecisionExplainer.class,pipeline);}
    @Test void predictionAndCounterfactualAreReadOnlyAndUseActualRoute(){State state=disrupted();AiFallbackPipeline pipeline=new AiFallbackPipeline(graph(),mapper);String before=mapper.valueToTree(state).toString();PredictionBatch predictions=pipeline.predict(state);assertEquals(210,predictions.trucks().getFirst().estimatedArrivalSec());CandidateAction candidate=reroute(pipeline,state);Evaluation evaluation=pipeline.evaluate(state,candidate);assertEquals(210,evaluation.beforeArrivalSec());assertEquals(50,evaluation.afterArrivalSec());assertEquals(-160,evaluation.travelDeltaSec());assertTrue(evaluation.validation().valid());assertEquals(before,mapper.valueToTree(state).toString());assertFalse(evaluation.source().calibrated());assertEquals("SIMULATED_PREDICTION",evaluation.source().provenance());}
    @Test void candidateFingerprintRejectsChangedClockOrRoute(){State state=disrupted();AiFallbackPipeline pipeline=new AiFallbackPipeline(graph(),mapper);CandidateAction candidate=reroute(pipeline,state);state.clockSec=.1;ApiException error=assertThrows(ApiException.class,()->pipeline.evaluate(state,candidate));assertEquals(409,error.status);}
    @Test void fictionalActionsAndAlteredRecommendationAreRejected(){State state=disrupted();AiFallbackPipeline pipeline=new AiFallbackPipeline(graph(),mapper);CandidateAction good=reroute(pipeline,state);assertThrows(ApiException.class,()->pipeline.evaluate(state,new CandidateAction(good.id(),good.truckId(),"SWAP_DRIVER",good.recommendationId(),good.stateFingerprint(),good.source())));assertThrows(ApiException.class,()->pipeline.evaluate(state,new CandidateAction(good.id(),good.truckId(),good.action(),"invented",good.stateFingerprint(),good.source())));}
    @Test void recommendationsNeverExecuteAndReplayConstraintBlocksMutation(){State state=disrupted();state.replaying=true;AiFallbackPipeline pipeline=new AiFallbackPipeline(graph(),mapper);String before=mapper.valueToTree(state).toString();RecommendationResult recommendation=pipeline.recommend(state,"T1");assertNull(recommendation.selected());assertTrue(recommendation.evaluations().stream().allMatch(e->!e.validation().valid()));assertEquals(before,mapper.valueToTree(state).toString());}
    @Test void snapshotsSeparateInputsPredictionsAndRealizedLabels(){State state=state();AiFallbackPipeline pipeline=new AiFallbackPipeline(graph(),mapper);GraphSnapshotExporter.GraphSnapshot first=pipeline.snapshot(state);assertTrue(first.realizedLabels().isEmpty());assertTrue(first.predictions().stream().anyMatch(t->t.target().equals("estimated_arrival_sec")));assertFalse(first.nodes().getFirst().features().containsKey("arrival_sec"));assertEquals("SIMULATED",first.provenance().operations());assertEquals("SIMULATED_OUTCOME",first.provenance().outcomeLabels());Truck truck=state.trucks.getFirst();truck.arrivalSec=20;truck.status="ARRIVED";state.clockSec=20;GraphSnapshotExporter.GraphSnapshot arrived=pipeline.snapshot(state);assertEquals(2,arrived.realizedLabels().size());assertTrue(arrived.realizedLabels().stream().allMatch(t->t.provenance().equals("SIMULATED_OUTCOME")));assertEquals("2026-10-09T09:00:20+05:30",arrived.simulationTime().simulationTimestamp());}
    @Test void unknownDriverEtaIsExplicitAndHasNoOperationalArrivalTarget(){State state=disrupted();Driver driver=new Driver();driver.id="D1";driver.name="Unit fixture";driver.available=false;driver.shiftEndSec=1000;state.operations.drivers.add(driver);Warehouse warehouse=new Warehouse();warehouse.id="W1";warehouse.location=state.trucks.getFirst().destination;warehouse.nodeId=3;warehouse.dockCapacity=1;state.operations.warehouses.add(warehouse);Dock dock=new Dock();dock.id="K1";dock.warehouseId="W1";dock.serviceSec=10;dock.openUntilSec=1000;state.operations.docks.add(dock);Assignment assignment=new Assignment();assignment.truckId="T1";assignment.driverId="D1";assignment.dockId="K1";assignment.reservationStartSec=20;assignment.reservationEndSec=30;state.operations.assignments.add(assignment);state.trucks.getFirst().etaKnown=false;state.operations.graph=new OperationalDependencyGraph().build(state);AiFallbackPipeline pipeline=new AiFallbackPipeline(graph(),mapper);assertNull(pipeline.predict(state).trucks().getFirst().estimatedArrivalSec());Evaluation evaluation=pipeline.evaluate(state,reroute(pipeline,state));assertFalse(evaluation.afterEtaKnown());assertTrue(evaluation.afterImpacts().stream().anyMatch(i->i.code().equals("DELIVERY_ETA_UNKNOWN")));assertTrue(pipeline.snapshot(state).predictions().stream().noneMatch(t->t.target().equals("estimated_arrival_sec")));}
    @Test void snapshotMissingValuesUseExplicitMaskAndDeterministicContent(){State state=state();List<GraphNode> nodes=new ArrayList<>(state.operations.graph.nodes());nodes.add(new GraphNode("WAREHOUSE:MISSING","WAREHOUSE","MISSING",Map.of(),"SIMULATED"));state.operations.graph=new GraphView("cascadeshield.operational-graph/1.0",0,state.networkId,nodes,List.of(),"SIMULATED");GraphSnapshotExporter exporter=new GraphSnapshotExporter(graph(),mapper);GraphSnapshotExporter.GraphSnapshot a=exporter.snapshot(state),b=exporter.snapshot(mapper.convertValue(state,State.class));assertEquals(mapper.valueToTree(a),mapper.valueToTree(b));GraphSnapshotExporter.SnapshotNode missing=a.nodes().stream().filter(n->n.id().equals("WAREHOUSE:MISSING")).findFirst().orElseThrow();assertTrue(missing.features().values().stream().allMatch(Objects::isNull));assertTrue(missing.availableMask().values().stream().noneMatch(Boolean::booleanValue));}
    @Test void identicalReplayInputsKeepFeatureAndOutcomeContentAcrossAdministrativeRuns(){State one=state(),two=mapper.convertValue(one,State.class);two.runId=UUID.randomUUID();GraphSnapshotExporter exporter=new GraphSnapshotExporter(graph(),mapper);var a=exporter.snapshot(one);var b=exporter.snapshot(two);assertNotEquals(a.runId(),b.runId());assertEquals(a.nodes(),b.nodes());assertEquals(a.edges(),b.edges());assertEquals(a.predictions(),b.predictions());assertEquals(a.realizedLabels(),b.realizedLabels());}
    @Test void futureScheduledCompletionCannotBecomeAnOutcomeLabel(){State state=state();state.trucks.getFirst().arrivalSec=20;state.trucks.getFirst().baselineArrivalSec=10;state.clockSec=15;assertTrue(new GraphSnapshotExporter(graph(),mapper).snapshot(state).realizedLabels().isEmpty());}
    @Test void candidateSourceVersionCannotBeForged(){State state=disrupted();AiFallbackPipeline pipeline=new AiFallbackPipeline(graph(),mapper);CandidateAction good=reroute(pipeline,state);CandidateAction forged=new CandidateAction(good.id(),good.truckId(),good.action(),good.recommendationId(),good.stateFingerprint(),new Source("FAKE_LEARNED_MODEL","invented","OBSERVED_HISTORICAL",true,""));assertThrows(ApiException.class,()->pipeline.evaluate(state,forged));}
}
